
(function(){
 const priority=['bsn','optimum nutrition','on','dymatize','muscletech','muscle tech','basic','integral','nutramerican','proscience','sascha','sasha'];
 const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 const aliases=q=>{let a=[q];if(q.includes('creatina'))a.push(q.replace(/creatina/g,'creatine'));if(q.includes('creatine'))a.push(q.replace(/creatine/g,'creatina'));return [...new Set(a)]};
 function ps(){try{return Array.isArray(window.PRODUCTS)?window.PRODUCTS:(Array.isArray(PRODUCTS)?PRODUCTS:[])}catch(e){return []}}
 function brandRank(p){const b=norm(p.brand||p.marca);let i=priority.findIndex(x=>b===x||b.includes(x));return i<0?999:i}
 function score(p,q){const text=norm([p.name,p.nombre,p.brand,p.marca,p.category,p.categoria,p.presentation,p.presentacion,p.description,p.descripcion,p.flavor,p.sabor].filter(Boolean).join(' '));let hit=0;for(const a of aliases(q)){const toks=norm(a).split(/\s+/).filter(Boolean);if(toks.length&&toks.every(t=>text.includes(t)))hit=Math.max(hit,100+toks.length*8);else hit=Math.max(hit,toks.filter(t=>text.includes(t)).length*5)}if(!hit)return 0;const b=brandRank(p);if(b<999)hit+=1000-b*10;const nq=norm(q);if(nq==='creatina'||nq==='creatine'){const n=norm(p.name||p.nombre),br=norm(p.brand||p.marca),pres=norm(p.presentation||p.presentacion);if((br.includes('muscletech')||br.includes('muscle tech'))&&n.includes('platinum')&&(pres.includes('90')||n.includes('90'))&&(pres.includes('serv')||n.includes('serv')))hit+=100000}return hit}
 function getResults(q){q=norm(q);if(!q)return[];const arr=ps().map(p=>({p,s:score(p,q)})).filter(x=>x.s>0).sort((a,b)=>b.s-a.s||brandRank(a.p)-brandRank(b.p));const out=[],seen=new Set();for(const x of arr){const key=String(x.p.id);if(seen.has(key))continue;seen.add(key);out.push(x.p);if(out.length>=15)break}return out}
 function price(p){try{return typeof priceOf==='function'?priceOf(p):Number(p.price||p.precio||0)}catch(e){return Number(p.price||p.precio||0)}}
 function money(v){try{return typeof fmt==='function'?fmt(v):new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v)}catch(e){return '$'+Number(v||0).toLocaleString('es-CO')}}
 function img(p){return p.image||p.imagen||''}
 window.liftQuickListSearch=function(){const q=document.getElementById('liftQuickListInput')?.value||'';const rows=getResults(q);window.LIFT_QUICK_RESULTS=rows;const box=document.getElementById('liftQuickListResults');if(!box)return;if(!q.trim()){box.innerHTML='<div class="lqlEmpty">Escribe lo que te pidió el cliente.</div>';return}if(!rows.length){box.innerHTML='<div class="lqlEmpty">No encontré coincidencias reales.</div>';return}box.innerHTML=rows.map((p,i)=>`<label class="lqlRow"><input type="checkbox" data-lql="${i}" checked><img src="${img(p)}" alt=""><div><div class="lqlName">${p.name||p.nombre||''}</div><div class="lqlMeta">${p.brand||p.marca||''}${(p.presentation||p.presentacion)?' · '+(p.presentation||p.presentacion):''}</div></div><div class="lqlPrice">${money(price(p))}</div></label>`).join('')};
 function selected(){const rows=window.LIFT_QUICK_RESULTS||[];return [...document.querySelectorAll('[data-lql]:checked')].map(x=>rows[Number(x.dataset.lql)]).filter(Boolean)}
 window.liftOpenQuickList=function(){if(!document.body.classList.contains('liftAdminUnlocked'))return;document.getElementById('liftQuickListModal')?.classList.add('open');setTimeout(()=>document.getElementById('liftQuickListInput')?.focus(),50)};
 window.liftCloseQuickList=function(){document.getElementById('liftQuickListModal')?.classList.remove('open')};
 window.liftQuickListCopy=async function(){const rows=selected();if(!rows.length)return alert('Selecciona al menos un producto.');const q=document.getElementById('liftQuickListInput')?.value.trim()||'Productos disponibles';const t=[q.charAt(0).toUpperCase()+q.slice(1),'',...rows.map((p,i)=>`${i+1}. ${p.name||p.nombre} · ${p.brand||p.marca}${(p.presentation||p.presentacion)?' · '+(p.presentation||p.presentacion):''} · ${money(price(p))}`)].join('\n');try{await navigator.clipboard.writeText(t);if(typeof liftShareToast==='function')liftShareToast('Lista copiada')}catch(e){prompt('Copia la lista:',t)}};
 window.liftQuickListShare=async function(){const rows=selected();if(!rows.length)return alert('Selecciona al menos un producto.');const q=document.getElementById('liftQuickListInput')?.value.trim()||'Productos disponibles';const W=1080,rowH=150,H=180+rows.length*rowH+90,c=document.createElement('canvas');c.width=W;c.height=H;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#111';ctx.fillRect(0,0,W,120);ctx.fillStyle='#fff';ctx.font='700 34px Poppins,Arial';ctx.fillText('LIFT NUTRIENTES',50,52);ctx.font='500 24px Poppins,Arial';ctx.fillText(q.toUpperCase(),50,91);let y=145;for(let i=0;i<rows.length;i++){const p=rows[i];ctx.strokeStyle='#e8e8e8';ctx.beginPath();ctx.moveTo(50,y+rowH-8);ctx.lineTo(W-50,y+rowH-8);ctx.stroke();try{const im=new Image();im.crossOrigin='anonymous';im.src=img(p);await new Promise(r=>{im.onload=r;im.onerror=r});if(im.complete&&im.naturalWidth)ctx.drawImage(im,55,y+8,110,110)}catch(e){}ctx.fillStyle='#111';ctx.font='600 22px Poppins,Arial';ctx.fillText((p.name||p.nombre||'').slice(0,55),190,y+40);ctx.fillStyle='#666';ctx.font='400 17px Poppins,Arial';ctx.fillText(((p.brand||p.marca||'')+((p.presentation||p.presentacion)?' · '+(p.presentation||p.presentacion):'')).slice(0,65),190,y+72);ctx.fillStyle='#111';ctx.font='700 24px Poppins,Arial';ctx.fillText(money(price(p)),190,y+108);y+=rowH}ctx.fillStyle='#777';ctx.font='400 16px Poppins,Arial';ctx.fillText('Disponibilidad sujeta a inventario.',50,H-35);const blob=await new Promise(r=>c.toBlob(r,'image/png',.95));if(!blob)return;const file=new File([blob],'lift-lista-rapida.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Lift Nutrientes'});return}}catch(e){}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 function install(){const bar=document.querySelector('.top .bar');if(!bar||document.getElementById('liftQuickListBtn'))return;const b=document.createElement('button');b.id='liftQuickListBtn';b.type='button';b.title='Lista rápida';b.setAttribute('aria-label','Lista rápida');b.textContent='⚡';b.onclick=window.liftOpenQuickList;const search=bar.querySelector('.search');bar.insertBefore(b,search||null)}
 install();document.addEventListener('DOMContentLoaded',install,{once:true});new MutationObserver(install).observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('input',e=>{if(e.target?.id==='liftQuickListInput')window.liftQuickListSearch()});document.getElementById('liftQuickListModal')?.addEventListener('click',e=>{if(e.target.id==='liftQuickListModal')window.liftCloseQuickList()});
})();
